import java.util.*;
import java.lang.reflect.*;
import java.awt.Point;
import hulka.tilemanager.*;
public class PrintSpinnerOracle {
 static void set(Object o,String name,Object v)throws Exception{Field f=SpinnerHandler.class.getDeclaredField(name);f.setAccessible(true);f.set(o,v);} static void mix(SpinnerHandler h)throws Exception{Method m=SpinnerHandler.class.getDeclaredMethod("mix");m.setAccessible(true);m.invoke(h);} static String state(HexSpinnerManager tm){StringBuilder b=new StringBuilder();for(int i=0;i<tm.getTileCount();i++){if(i>0)b.append(';');b.append(tm.getOriginalTileIndex(i)).append('@').append(tm.getRotationCount(i));}return b.toString();}
 public static void main(String[]a)throws Exception{String mode=a[0];int w=Integer.parseInt(a[1]),h=Integer.parseInt(a[2]);if(mode.equals("geom")){HexSpinnerManager tm=new HexSpinnerManager(w,h);System.out.printf("%d,%d,%d,%d,%d,%d,%d,%d,%d,%d,%d\n",tm.getTileCount(),tm.getTilesAcross(),tm.getTilesDown(),tm.getTileWidth(),tm.getTileHeight(),tm.getTileSpacingX(),tm.getTileSpacingY(),tm.getLeftOffset(),tm.getTopOffset(),tm.getBoardWidth(),tm.getBoardHeight());Point p=null;for(int i=0;i<7;i++){p=tm.getTilePosition(i,p);System.out.printf("t%d=%d,%d\n",i,p.x,p.y);}for(int i=0;i<6;i++){p=tm.getVertexPosition(i,p);System.out.printf("v%d=%d,%d\n",i,p.x,p.y);}return;}if(mode.equals("mix")){long seed=Long.parseLong(a[3]);HexSpinnerManager tm=new HexSpinnerManager(w,h);SpinnerHandler sh=new SpinnerHandler(tm);set(sh,"random",new Random(seed));mix(sh);System.out.println(state(tm));return;}if(mode.equals("spin")){int v=Integer.parseInt(a[3]),dir=Integer.parseInt(a[4]);HexSpinnerManager tm=new HexSpinnerManager(w,h);tm.spin(v,dir);System.out.println(state(tm));System.out.println(Arrays.toString(tm.getChangedTiles(null)));}}
}
